const stop = new Set('a an the is are was were to of in on at my your you i it did do does me tell about what how why which can could would please and have has had for with this that'.split(' '));
export function answerQuestion(id, question, mode='science') {
 const bank=answers[id] || [];
 const tokens=question.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(t=>t.length>1&&!stop.has(t));
 if (!tokens.length || /ignore (all |your |the )?(sources|instructions)|invent|pretend.*(fact|real)|system prompt/i.test(question)) return {text:'I can help with this mission’s purpose, instruments, discoveries, location, and ending. Please choose a question below. I only use the NASA evidence in this exhibit.',refs:[],supported:false};
 const exact=bank.find(a=>a.q.toLowerCase()===question.trim().toLowerCase());
 const weights={life:5,alien:5,organisms:5,drill:4,stop:3,stopped:3,end:3,find:0.25,mission:0.5};
 const ranked=bank.map(a=>({a,score:a===exact?100:tokens.reduce((s,t)=>s+(a.tags.split(' ').some(k=>k===t || (t.length>4&&k.startsWith(t.slice(0,-1))))?(weights[t]||1):0),0)})).sort((a,b)=>b.score-a.score);
 if (!ranked[0] || ranked[0].score===0) return {text:'The evidence in this exhibit does not answer that question. Try asking about the mission, an instrument, a discovery, or why the hardware remains there.',refs:[],supported:false};
 return {text:ranked[0].a[mode==='story'?'story':'science'],refs:ranked[0].a.refs,supported:true};
}
export const suggestions=id=>(answers[id]||[]).slice(0,4).map(a=>a.q);
export function gradeInvestigation(id,choice,evidence){const a=artifacts.find(x=>x.id===id);return !!a&&choice===a.correct&&evidence===a.evidence;}
